 check("dcba".equals(SnapTubePlayerScript.signature(c,"fixture-player",js,"abcdefghijk","abcd")),"Chromium signature execution");check("abcd-n".equals(SnapTubePlayerScript.throttling(c,"fixture-player",js,"abcdefghijk","abcd")),"Chromium n execution");check("dcba".equals(SnapTubePlayerScript.signature(c,"fixture-player",js,"abcdefghijk","abcd")),"cached transform");passed.put("Original Java signature and n transforms through isolated Chromium plus cache");
