 List<MediaCandidate> h=MediaParser.parseHls("#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=1000000,RESOLUTION=1280x720\nvariant.m3u8\n","https://example.com/master.m3u8","fixture");check(h.size()==1&&h.get(0).height==720,"HLS variants");passed.put("Java HLS variant parsing");
